// Demo route: Aewol to Gwakji along Iljuseo-ro. Road geometry from OpenStreetMap contributors via OSRM.
(function () {
  const POINTS = [
    [33.46607, 126.32644], [33.46606, 126.32661], [33.46355, 126.32654], [33.46333, 126.32653],
    [33.46310, 126.32653], [33.46256, 126.32651], [33.46252, 126.32651], [33.46240, 126.32645],
    [33.46234, 126.32640], [33.46232, 126.32637], [33.46231, 126.32632], [33.46227, 126.32614],
    [33.46223, 126.32591], [33.46219, 126.32577], [33.46214, 126.32569], [33.46208, 126.32538],
    [33.46208, 126.32537], [33.46198, 126.32488], [33.46196, 126.32480], [33.46195, 126.32471],
    [33.46193, 126.32466], [33.46175, 126.32365], [33.46150, 126.32218], [33.46127, 126.32095],
    [33.46125, 126.32081], [33.46122, 126.32066], [33.46117, 126.32040], [33.46113, 126.32019],
    [33.46111, 126.32007], [33.46092, 126.31912], [33.46073, 126.31805], [33.46070, 126.31789],
    [33.46066, 126.31770], [33.46052, 126.31695], [33.46005, 126.31436], [33.46000, 126.31412],
    [33.45990, 126.31356], [33.45975, 126.31286], [33.45961, 126.31239], [33.45949, 126.31208],
    [33.45928, 126.31169], [33.45895, 126.31123], [33.45887, 126.31114], [33.45878, 126.31105],
    [33.45868, 126.31095], [33.45857, 126.31084], [33.45854, 126.31081], [33.45812, 126.31046],
    [33.45747, 126.31002], [33.45698, 126.30967], [33.45659, 126.30943], [33.45621, 126.30925],
    [33.45582, 126.30913], [33.45463, 126.30900], [33.45373, 126.30893], [33.45305, 126.30887],
    [33.45233, 126.30881], [33.45226, 126.30880], [33.45214, 126.30879], [33.45217, 126.30871],
    [33.45220, 126.30861], [33.45222, 126.30848], [33.45222, 126.30838], [33.45222, 126.30831],
    [33.45221, 126.30823], [33.45219, 126.30813], [33.45211, 126.30789], [33.45207, 126.30771],
    [33.45196, 126.30738], [33.45194, 126.30733], [33.45181, 126.30697], [33.45139, 126.30693],
    [33.45130, 126.30693], [33.45126, 126.30692], [33.45120, 126.30690], [33.45114, 126.30687],
    [33.45108, 126.30682], [33.45100, 126.30673], [33.45083, 126.30654], [33.45076, 126.30646],
    [33.45070, 126.30640], [33.45023, 126.30602],
  ];

  function dist(a, b) {
    const k = Math.PI / 180;
    const x = (b[1] - a[1]) * k * Math.cos(((a[0] + b[0]) / 2) * k);
    const y = (b[0] - a[0]) * k;
    return Math.hypot(x, y) * 6371000;
  }

  const cumulative = [0];
  for (let i = 1; i < POINTS.length; i++) cumulative.push(cumulative[i - 1] + dist(POINTS[i - 1], POINTS[i]));

  App.route = {
    points: POINTS,
    length: cumulative[cumulative.length - 1],
    maneuvers: [
      { routeM: 501, text: '잠시 후 오른쪽으로 일주서로에 진입합니다.' },
      { routeM: 2712, text: '잠시 후 오른쪽 방향입니다.' },
      { routeM: 2892, text: '잠시 후 왼쪽 방향입니다.' },
    ],
    // Metres along the route of the vertex nearest to a point.
    project(lat, lon) {
      let best = 0, bestD = Infinity;
      POINTS.forEach((p, i) => {
        const d = dist(p, [lat, lon]);
        if (d < bestD) { bestD = d; best = i; }
      });
      return cumulative[best];
    },
    // Position source for the demo: distance ahead of the car along the replayed route.
    ahead(posM, items) {
      return items.map(item => ({ ...item, distanceM: item.routeM - posM }));
    },
    pointAt(m) {
      for (let i = 1; i < POINTS.length; i++) {
        if (m <= cumulative[i]) {
          const f = (m - cumulative[i - 1]) / (cumulative[i] - cumulative[i - 1]);
          return POINTS[i - 1].map((v, j) => v + (POINTS[i][j] - v) * f);
        }
      }
      return POINTS[POINTS.length - 1];
    },
  };
})();
